gates the existence or presence of the noun it modifies.","example_pairs":[{"sentence":"無人至。","aligned_translation":"No one has arrived."},{"sentence":"無事可言。","aligned_translation":"There is nothing to say."},{"sentence":"無車而行。","aligned_translation":"Travel without a cart."},{"sentence":"無名之物。","aligned_translation":"A thing without a name."}]}]}
